parts = fragments(template)
names = dict.fromkeys(field for _, field in parts if field is not None)
for name in names:
    parts = [(literal + str(values[name]), None) if field == name else (literal, field)
             for literal, field in parts]
return "".join(literal for literal, _ in parts)

